draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // draw an apple
  ctx.fillStyle = 'red';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();

  // draw a banana
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.arc(W/2 + 100*Math.sin(t), H/2, 50, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();

  // draw a carrot
  ctx.fillStyle = 'orange';
  ctx.beginPath();
  ctx.rect(W/2 - 100*Math.sin(t), H/2, 20, 50);
  ctx.fill();
  ctx.stroke();

  // draw a stick figure eating
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 150, 20, 0, 2*Math.PI); // head
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 130);
  ctx.lineTo(W/2, H/2 - 50); // body
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 70);
  ctx.lineTo(W/2 - 30, H/2 - 30); // arm
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 70);
  ctx.lineTo(W/2 + 30, H/2 - 30); // arm
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 50);
  ctx.lineTo(W/2 - 20, H/2 + 20); // leg
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 50);
  ctx.lineTo(W/2 + 20, H/2 + 20); // leg
  ctx.stroke();

  ctx.restore();
}
